import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "./DetailsProduct.scss";

const DetailsProduct = () => {
  const { productId } = useParams();
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        const response = await fetch("/products.json");

        if (!response.ok) {
          throw new Error(`Erro na requisição: ${response.status}`);
        }

        const data = await response.json();
        console.log("Dados carregados:", data); // Verificar os dados carregados

        const selectedProduct = data.find((p) => String(p.referenceId) === String(productId));

        if (!selectedProduct) {
          console.warn("Produto não encontrado!");
        } else {
          console.log("Produto selecionado:", selectedProduct); // Verificar se o produto foi encontrado
        }

        setProduct(selectedProduct);
      } catch (error) {
        console.error("Erro ao carregar o produto:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchProduct();
  }, [productId]);

  if (loading) return <p>Carregando...</p>;
  if (!product) return <p>Produto não encontrado.</p>;

  return (
    <div className="details-product">
      {/* Galeria de Imagens */}
      <div className="product-gallery">
        {product?.imageUrl ? (
          Array.isArray(product.imageUrl) ? (
            product.imageUrl.map((image, index) => (
              <img key={index} src={image} alt={`Produto ${index + 1}`} />
            ))
          ) : (
            <img src={product.imageUrl} alt="Produto" />
          )
        ) : (
          <img src="/no-image.jpg" alt="Imagem não disponível" />
        )}
      </div>

      {/* Informações do Produto */}
      <div className="product-info">
        <h1>{product?.productName || "Nome do Produto Indisponível"}</h1>
        <p className="description">{product?.metaTagDescription || "Sem descrição disponível"}</p>
        <p className="price">
          {product?.installments
            ? `${product.installments}x de R$ ${product.priceParcelado?.toFixed(2) || "Preço indisponível"}`
            : "Parcelamento não disponível"}
        </p>
        <button className="add-to-cart">ADICIONAR À SACOLA</button>
      </div>
    </div>
  );
};

export default DetailsProduct;
